from content.authoring import E, J, L, P, Q, R, T

SCANNER = 'import java.util.Scanner;'
READ_NAME = J('Scanner in = new Scanner(System.in);\nString name = in.nextLine();\nSystem.out.println("Hello, " + name + "!");', SCANNER)
SAFE_COUNT = J('Scanner in = new Scanner(System.in);\nif (in.hasNextInt()) {\n    int count = in.nextInt();\n    System.out.println("Count: " + count);\n} else {\n    System.out.println("Invalid integer");\n}', SCANNER)
TEXT_LABEL = J('Scanner in = new Scanner(System.in);\nString title = in.nextLine().trim();\nif (title.isEmpty()) {\n    System.out.println("Empty title");\n} else {\n    System.out.println(title.toUpperCase(java.util.Locale.ROOT));\n    System.out.println(title.length());\n}', SCANNER)

LESSONS = [
L('read-input', 'Read a Whole Line', 'Accept a real name, including spaces, rather than one token.',
  ['Scanner reads text from System.in. Import java.util.Scanner, construct a Scanner, then call nextLine to read one line without its ending newline. The returned value is a String and can contain spaces.',
   'In the Studio, put each input line in Standard input before Run. Input is supplied as a finite batch; it is not a live terminal prompt. A program cannot read another line after the batch ends without checking availability. This first task requires exactly one supplied line.',
   'Keep the input contract visible: one full name, including spaces and non-English characters. Do not use next for a full name, because it stops at whitespace. Do not bake a particular name into the program.'],
  ['Read a full line into a String.', 'Match the input contract and preserve spaces.'],
  E(READ_NAME, 'Hello, Ada Lovelace!\n', ['Construct the Scanner.', 'Read the whole first line.', 'Combine the greeting with the supplied name.'], 'Ada Lovelace\n'),
  Q('Input is Lin Mei. What exact line is printed?', READ_NAME, 'Hello, Lin Mei!', 'nextLine preserves the space between Lin and Mei.'),
  R('Why should a full-name prompt use nextLine rather than next? What input does this program require?', 'next reads only one whitespace-delimited token; nextLine reads the full name. This program needs one complete input line.', ['I distinguish a token from a full line.', 'I state the one-line input contract.']),
  P('Read one full book title and print Selected: followed by a space and that title. Preserve its internal spaces.', J('Scanner in = new Scanner(System.in);\nString title = in.nextLine();\nSystem.out.println("Selected: " + title);', SCANNER), [T('title with spaces', 'The Long Orbit\n', 'Selected: The Long Orbit\n'), T('UTF-8 title', '星の旅\n', 'Selected: 星の旅\n')], starter=J('Scanner in = new Scanner(System.in);\nString title = in.nextLine();\n// Print the selected title.', SCANNER), hints=['Use nextLine for the title.', 'Concatenate the label, a space, and the input String.']),
  diagram={'kind':'sequence','nodes':['System.in: Ada Lovelace + newline','nextLine() → Ada Lovelace','println greeting + name'],'edges':[[0,1],[1,2]]}),
L('scanner-lines', 'Tokens, Lines & an Input Guard', 'Avoid leftover newlines and reject a wrong numeric token.',
  ['nextInt reads a numeric token but leaves the line ending after it. A following nextLine consumes the remaining portion of that line, which can be empty. If you intentionally mix these methods, consume that remainder once before reading the next full line.',
   'hasNextInt checks whether the next token can be read as int, without consuming it. A small guard uses if (condition) { valid work } else { invalid work }. Only the true branch runs. This introduces the branch form needed for safe input; the decisions stage will deepen it.',
   'This guard reports invalid input and ends this run. It does not retry yet. The loops stage adds retry and exit behavior. Supplying fewer lines than the stated contract is still a different error from a nonnumeric token.'],
  ['Explain the leftover-line pitfall.', 'Guard one numeric read instead of allowing an input mismatch crash.'],
  E(SAFE_COUNT, 'Count: 4\n', ['hasNextInt checks the token.', 'The true branch reads it.', 'An invalid token follows the else branch.'], '4\n'),
  Q('What is printed for the input pear?', SAFE_COUNT, 'Invalid integer', 'hasNextInt is false, so nextInt is never called.'),
  R('After nextInt reads 7 from a line containing only 7, why can the next nextLine return an empty String?', 'The numeric token was consumed but its line ending remains. nextLine returns the empty remainder and consumes that ending. Consume it before reading the next actual text line.', ['I distinguish consuming a token from consuming its line.', 'I describe one intentional remainder read.']),
  P('Read an integer age on the first line and a full name on the second. If the first token is not an int, print Invalid age and stop. Otherwise print name + " / " + age. Consume the numeric line remainder before the name.', J('Scanner in = new Scanner(System.in);\nif (in.hasNextInt()) {\n    int age = in.nextInt();\n    in.nextLine();\n    String name = in.nextLine();\n    System.out.println(name + " / " + age);\n} else {\n    System.out.println("Invalid age");\n}', SCANNER), [T('two-line form', '24\nAda Lovelace\n', 'Ada Lovelace / 24\n'), T('invalid token', 'pear\n', 'Invalid age\n'), T('zero boundary', '0\nNew Reader\n', 'New Reader / 0\n')], starter=J('Scanner in = new Scanner(System.in);\n// Guard the age token, then consume its line remainder before the full name.', SCANNER), hints=['Use hasNextInt before nextInt.', 'Call nextLine once for the remainder and once for the name.']),
  diagram={'kind':'branch','nodes':['hasNextInt?','YES: nextInt → consume remainder → nextLine','NO: Invalid age'],'edges':[[0,1],[0,2]]}),
L('strings-and-characters', 'Clean & Inspect Text', 'Trim input, compare text length, and respect character boundaries.',
  ['String values are immutable: trim and toUpperCase return a new String rather than changing the original variable. Assign the result if you want to use the changed text. trim removes common leading/trailing whitespace; internal spaces remain.',
   'length counts UTF-16 code units. charAt returns one code unit and requires an index from 0 through length - 1. An empty String has no first character. Check isEmpty before charAt(0). A displayed Unicode character can span more than one char; do not equate char with every human-visible symbol.',
   'Use Locale.ROOT for deterministic case conversion in these nonlocalized exercises. Normalize only as the input contract requires. Trimming a name does not justify removing its internal spaces or silently changing user data.'],
  ['Use a returned String value rather than expecting mutation.', 'Guard empty text before accessing its first position.'],
  E(TEXT_LABEL, 'ORBIT\n5\n', ['Read and trim the title.', 'Reject an empty title.', 'For nonempty text, print uppercase and length.'], '  Orbit  \n'),
  Q('For input containing three spaces only, what does the worked program print?', TEXT_LABEL, 'Empty title', 'trim returns an empty String; the guarded valid branch is not entered.'),
  R('What must you check before charAt(0), and what does String.length actually count?', 'Check that the String is nonempty. length counts UTF-16 code units, so one displayed symbol need not equal one char.', ['I guard against an empty String.', 'I avoid claiming every displayed Unicode symbol is one char.']),
  P('Read one line, trim its ends, and print Empty for a blank result. Otherwise print First: followed by its first char, then Length: followed by length. Use one space after each colon. These cases use ASCII text.', J('Scanner in = new Scanner(System.in);\nString word = in.nextLine().trim();\nif (word.isEmpty()) {\n    System.out.println("Empty");\n} else {\n    System.out.println("First: " + word.charAt(0));\n    System.out.println("Length: " + word.length());\n}', SCANNER), [T('trim ends', '  Orbit  \n', 'First: O\nLength: 5\n'), T('empty boundary', '   \n', 'Empty\n'), T('single character', 'A\n', 'First: A\nLength: 1\n')], starter=J('Scanner in = new Scanner(System.in);\nString word = in.nextLine().trim();\n// Guard the empty String before charAt(0).', SCANNER), hints=['Use isEmpty to choose the empty branch.', 'The first zero-based index is 0.'])),
]
